import java.util.Arrays; public final class BookingReceipt {private final String id;private final String[] seats;public BookingReceipt(String i,String[]s){id=i;seats=Arrays.copyOf(s,s.length);}public String[]getSeatNumbers(){return Arrays.copyOf(seats,seats.length);}public BookingReceipt withSeatNumbers(String[]s){return new BookingReceipt(id,s);}public static void main(String[]a){System.out.println(new BookingReceipt("B1",new String[]{"A1"}).getSeatNumbers()[0]);}}
